#!/usr/bin/env node
// Database migrations (db/migrations, generated by drizzle-kit) are applied by
// the running app. A migration that has shipped must never change: the app
// refuses to start serving user data if an applied migration's hash differs.
// So, against the base commit:
//   - existing .sql files must not be modified, renamed or deleted;
//   - every .sql file must be listed in meta/_journal.json, and vice versa.
import { execFileSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'

const ROOT = process.cwd()
const DIR = 'db/migrations'

function fail(message) {
  console.error(`Migration policy: ${message}`)
  process.exit(1)
}

function git(args) {
  try {
    return execFileSync('git', args, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim()
  } catch {
    return null
  }
}

const sqlFiles = fs.readdirSync(path.join(ROOT, DIR)).filter((file) => file.endsWith('.sql')).sort()
const journal = JSON.parse(fs.readFileSync(path.join(ROOT, DIR, 'meta', '_journal.json'), 'utf8'))
const journalFiles = journal.entries.map((entry) => `${entry.tag}.sql`).sort()

const unlisted = sqlFiles.filter((file) => !journalFiles.includes(file))
const missing = journalFiles.filter((file) => !sqlFiles.includes(file))
if (unlisted.length) fail(`not in meta/_journal.json: ${unlisted.join(', ')} (generate migrations with npm run db:generate)`)
if (missing.length) fail(`listed in meta/_journal.json but missing: ${missing.join(', ')}`)

const baseSha = process.env.BASE_SHA?.trim()
const headSha = process.env.HEAD_SHA?.trim() || 'HEAD'
if (!baseSha || /^0+$/.test(baseSha)) {
  console.log(`Migration policy OK (${sqlFiles.length} migrations checked locally).`)
  process.exit(0)
}

const changes = git(['diff', '--name-status', '--find-renames', baseSha, headSha, '--', `${DIR}/*.sql`])
if (changes === null) {
  console.log(`Migration policy OK (${sqlFiles.length} migrations; base ${baseSha} not available to compare).`)
  process.exit(0)
}

const forbidden = changes
  .split('\n')
  .filter(Boolean)
  .map((line) => line.split('\t'))
  .filter(([status]) => !status.startsWith('A'))
  .map(([status, ...files]) => `${status} ${files.join(' -> ')}`)

if (forbidden.length) {
  fail(`applied migrations must never change; add a new one instead. Changed: ${forbidden.join('; ')}`)
}

console.log(`Migration policy OK (${sqlFiles.length} migrations, none of the existing ones changed).`)
